<?php require 'config.php';require_login();$cart=$_SESSION['cart']??[];if(!$cart){flash('warning','Giỏ hàng đang trống.');redirect('cart.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(!$name||!$phone||!$address){flash('danger','Vui lòng nhập đầy đủ thông tin nhận hàng.');redirect('checkout.php');}
try{$pdo->beginTransaction();$total=0;foreach($cart as $it){$st=$pdo->prepare("SELECT id,title,price FROM books WHERE id=? AND status='active' FOR UPDATE");$st->execute([$it['id']]);$b=$st->fetch();if(!$b)throw new Exception('Một giáo trình trong giỏ không còn khả dụng.');$total+=$b['price']*$it['quantity'];}
$st=$pdo->prepare("INSERT INTO orders(user_id,customer_name,phone,address,total,status) VALUES(?,?,?,?,?,'pending')");$st->execute([user()['id'],$name,$phone,$address,$total]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO order_items(order_id,book_id,book_title,price,quantity) VALUES(?,?,?,?,?)");foreach($cart as $it){$st=$pdo->prepare("SELECT title,price FROM books WHERE id=?");$st->execute([$it['id']]);$b=$st->fetch();$ins->execute([$oid,$it['id'],$b['title'],$b['price'],$it['quantity']]);}$pdo->commit();unset($_SESSION['cart']);flash('success','Đặt hàng thành công. Mã đơn #'.$oid);redirect('orders.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Không thể đặt hàng: '.$e->getMessage());redirect('checkout.php');}}
header_html('Đặt hàng');$total=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$cart));?><h1 class="fw-bold">Thông tin đặt hàng</h1><div class="row g-4"><div class="col-lg-7"><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="form-label">Họ tên người nhận</label><input class="form-control mb-3" name="name" value="<?=e(user()['name'])?>" required><label class="form-label">Số điện thoại</label><input class="form-control mb-3" name="phone" required><label class="form-label">Địa chỉ nhận hàng</label><textarea class="form-control mb-3" name="address" rows="3" required></textarea><button class="btn btn-success btn-lg">Xác nhận đặt hàng</button></form></div><div class="col-lg-5"><div class="card p-4 border-0 shadow-sm"><h5>Tóm tắt đơn hàng</h5><?php foreach($cart as $it):?><div class="d-flex justify-content-between py-2 border-bottom"><span><?=e($it['title'])?> × <?=$it['quantity']?></span><strong><?=money($it['price']*$it['quantity'])?></strong></div><?php endforeach;?><h4 class="mt-3">Tổng: <span class="price"><?=money($total)?></span></h4></div></div></div><?php footer_html();?>
